SELECT game_id AS "gameId", entity_id AS "entityId", resource_key AS "resourceKey", initial_value AS "initialValue", max_value AS "maxValue", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.entity_resource_values WHERE game_id = #{gameId}
AND entity_id = #{entityId}
ORDER BY entity_id, resource_key
